public class SplitExplorerPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String describe(java.awt.Component c) {
        if (c == null) {
            return "(nothing)";
        }
        return c.getClass().getSimpleName() + " named " + c.getName();
    }

    static String viewName(java.awt.Component scroll) {
        if (!(scroll instanceof javax.swing.JScrollPane)) {
            return "(not a JScrollPane)";
        }
        java.awt.Component view = ((javax.swing.JScrollPane) scroll).getViewport().getView();
        return describe(view);
    }

    public static void main(String[] args) {
        try {
            SplitExplorerPanel panel = new SplitExplorerPanel();
            check("panel uses a BorderLayout", true, panel.getLayout() instanceof java.awt.BorderLayout);
            java.awt.Component center = null;
            if (panel.getLayout() instanceof java.awt.BorderLayout) {
                center = ((java.awt.BorderLayout) panel.getLayout())
                        .getLayoutComponent(java.awt.BorderLayout.CENTER);
            }
            check("CENTER holds the split pane", "JSplitPane named split", describe(center));
            if (center instanceof javax.swing.JSplitPane) {
                javax.swing.JSplitPane split = (javax.swing.JSplitPane) center;
                check("split is horizontal", javax.swing.JSplitPane.HORIZONTAL_SPLIT, split.getOrientation());
                check("divider location", 150, split.getDividerLocation());
                check("left side", "JScrollPane named navScroll", describe(split.getLeftComponent()));
                check("left scroll pane views nav", "JPanel named nav", viewName(split.getLeftComponent()));
                check("right side", "JScrollPane named detailScroll", describe(split.getRightComponent()));
                check("right scroll pane views detail", "JTextArea named detail",
                        viewName(split.getRightComponent()));
            } else {
                failures += 6;
                System.out.println("FAIL  no JSplitPane in CENTER, cannot inspect its sides");
            }
            java.awt.Component navComp = find(panel, "nav");
            if (navComp instanceof javax.swing.JPanel) {
                javax.swing.JPanel nav = (javax.swing.JPanel) navComp;
                check("nav uses a BoxLayout", true, nav.getLayout() instanceof javax.swing.BoxLayout);
                if (nav.getLayout() instanceof javax.swing.BoxLayout) {
                    check("nav stacks vertically", javax.swing.BoxLayout.Y_AXIS,
                            ((javax.swing.BoxLayout) nav.getLayout()).getAxis());
                } else {
                    failures++;
                    System.out.println("FAIL  cannot read the axis without a BoxLayout");
                }
                check("three nav buttons", 3, nav.getComponentCount());
                if (nav.getComponentCount() == 3) {
                    check("nav button order", "homeButton,filesButton,trashButton",
                            nav.getComponent(0).getName() + "," + nav.getComponent(1).getName()
                                    + "," + nav.getComponent(2).getName());
                } else {
                    failures++;
                    System.out.println("FAIL  nav does not hold three buttons, cannot check their order");
                }
            } else {
                failures += 4;
                System.out.println("FAIL  nav panel not reachable by name from the tree");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

