import java.awt.BorderLayout;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSplitPane;
import javax.swing.JTextArea;

public class SplitExplorerPanel extends JPanel {

    private final JPanel nav = new JPanel();
    private final JButton homeButton = new JButton("Home");
    private final JButton filesButton = new JButton("Files");
    private final JButton trashButton = new JButton("Trash");
    private final JTextArea detail = new JTextArea(10, 30);

    public SplitExplorerPanel() {
        nav.setName("nav");
        homeButton.setName("homeButton");
        filesButton.setName("filesButton");
        trashButton.setName("trashButton");
        detail.setName("detail");
        assemble();
    }

    private void assemble() {
        nav.setLayout(new BoxLayout(nav, BoxLayout.Y_AXIS));
        nav.add(homeButton);
        nav.add(filesButton);
        nav.add(trashButton);

        JScrollPane navScroll = new JScrollPane(nav);
        navScroll.setName("navScroll");
        JScrollPane detailScroll = new JScrollPane(detail);
        detailScroll.setName("detailScroll");

        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, navScroll, detailScroll);
        split.setName("split");
        split.setDividerLocation(150);

        setLayout(new BorderLayout());
        add(split, BorderLayout.CENTER);
    }
}
